// DO NOT EDIT: This file was auto generated by egautotest.

func TestDebuggingQueryerQueryRow(t *testing.T) {
	t.Run("returns a scannable row", func(t *testing.T) {
		db := sqltestx.DuckDB(t)
		dq := sqlx.Debug(db)

		row := dq.QueryRow(`SELECT 7`)
		var v int
		require.NoError(t, row.Scan(&v))
		require.Equal(t, 7, v)
	})

	t.Run("passes a single argument through", func(t *testing.T) {
		db := sqltestx.DuckDB(t)
		dq := sqlx.Debug(db)

		row := dq.QueryRow(`SELECT ?`, 42)
		var v int
		require.NoError(t, row.Scan(&v))
		require.Equal(t, 42, v)
	})

	t.Run("passes multiple arguments through", func(t *testing.T) {
		db := sqltestx.DuckDB(t)
		dq := sqlx.Debug(db)

		row := dq.QueryRow(`SELECT ? + ?`, 3, 4)
		var v int
		require.NoError(t, row.Scan(&v))
		require.Equal(t, 7, v)
	})

	t.Run("scans a string value", func(t *testing.T) {
		db := sqltestx.DuckDB(t)
		dq := sqlx.Debug(db)

		row := dq.QueryRow(`SELECT 'hello'`)
		var v string
		require.NoError(t, row.Scan(&v))
		require.Equal(t, "hello", v)
	})

	t.Run("no rows reports sql.ErrNoRows", func(t *testing.T) {
		db := sqltestx.DuckDB(t)
		dq := sqlx.Debug(db)

		row := dq.QueryRow(`SELECT * FROM range(0)`)
		var v int
		require.ErrorIs(t, row.Scan(&v), sql.ErrNoRows)
	})
}
